-- PEMULIHAN paket y5-pengumuman-kedua-26okt: kembalikan variabel 7063 ke isi lama (penjaga MD5 isi baru).
SET NAMES latin1;
UPDATE abt_variabel SET sql_query = , modified = NOW()
  WHERE no_var = 7063 AND MD5(sql_query) = '3a7efb779860a3f8d3259c635c70f575';
SELECT ROW_COUNT() AS baris_dipulihkan;
SELECT IF((SELECT COUNT(*) FROM abt_variabel WHERE no_var = 7063 AND MD5(sql_query) = '66657b95ba227dbee045fbef8ab01c6e') = 1, 'PULIH COCOK', 'PULIH TIDAK COCOK') AS hasil;
